&lt;div class=&quot;BDtitre&quot;&gt;Dragon de magma v&#233;n&#233;rable&lt;div style=&quot;float:right;&quot;&gt;FP 17&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Dragon&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Dragon.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Montagnes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Montagnes.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Extraplanaire&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Extraplanaire.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;i&gt;Source : Bestiaire 2, p.107&lt;/i&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;PX&lt;/b&gt; 102 400&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Extraplanaire.html&quot; title=&quot;Extraplanaire (sous-type)&quot;&gt;extraplanaire&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Feu.html&quot; title=&quot;Feu (sous-type)&quot;&gt;Feu&lt;/a&gt;) de taille TG, CN&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init&lt;/b&gt; +4 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dragon#Sensdraconiques.html&quot; title=&quot;sens draconiques&quot;&gt;sens draconiques&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +32&lt;/li&gt;&lt;li&gt;&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dragon.html#PRESENCETERRIFIANTE&quot; title=&quot;Les dragons v&#233;ritables&quot;&gt;pr&#233;sence terrifiante&lt;/a&gt; (90 m (60 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), DD 26)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA&lt;/b&gt; 39, contact 8, pris au d&#233;pourvu 39 (naturelle +31, taille -2)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv&lt;/b&gt; 310 (23d12+161)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f&lt;/b&gt; +13, &lt;b&gt;Vig&lt;/b&gt; +22, &lt;b&gt;Vol&lt;/b&gt; +21&lt;/li&gt;&lt;li&gt;&lt;b&gt;Immunit&#233;s&lt;/b&gt; feu, paralysie, sommeil ; &lt;b&gt;RD&lt;/b&gt; 15/magie ; &lt;b&gt;RM&lt;/b&gt; 28&lt;/li&gt;&lt;li&gt;&lt;b&gt;Faiblesses&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vuln&#233;rabilit&#233;s-(Capacit&#233;).html&quot; title=&quot;Vuln&#233;rabilit&#233;s (Ext ou Sur)&quot;&gt;vuln&#233;rabilit&#233;&lt;/a&gt; au froid&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD&lt;/b&gt; 12 m (8 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), vol 60 m (40 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) (m&#233;diocre)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +33 (2d8+18/19–20 plus 10 feu) et 2 griffes, +33 (2d6+12/19–20) et coup de queue, +31 (2d6+18) et 2 ailes, +31 (1d8+6)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Espace&lt;/b&gt; 4,50 m (3 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) ; &lt;b&gt;Allonge&lt;/b&gt; 3 m (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) (4,50 m (3 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) pour la morsure)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dragon#Ecrasement.html&quot; title=&quot;&#233;crasement&quot;&gt;&#233;crasement&lt;/a&gt;, souffle (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Defcone.html&quot; title=&quot;c&#244;ne&quot;&gt;c&#244;ne&lt;/a&gt; de 15 m (10 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), 20d6 feu plus sp&#233;cial, DD 28), souffle de magma&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (NLS 23 ; concentration +28)&lt;ul&gt;&lt;li&gt;Constant — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-Feu.html&quot; title=&quot;Bouclier de feu&quot;&gt;bouclier de feu&lt;/a&gt;&lt;/i&gt; (chaud)&lt;/li&gt;&lt;li&gt;&#192; volont&#233; — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;mains br&#251;lantes&lt;/a&gt;&lt;/i&gt; (DD 16), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Feu.html&quot; title=&quot;Mur de feu&quot;&gt;mur de feu&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayon-Ardent.html&quot; title=&quot;Rayon ardent&quot;&gt;rayon ardent&lt;/a&gt;&lt;/i&gt;&lt;/li&gt;&lt;li&gt;3/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boule-De-Feu-&#192;-Retardement.html&quot; title=&quot;Boule de feu &#224; retardement&quot;&gt;boule de feu &#224; retardement&lt;/a&gt;&lt;/i&gt; (DD 22)&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sorts connus&lt;/b&gt; (NLS 15 ; concentration +20)&lt;ul&gt;&lt;li&gt;7&lt;sup&gt;e&lt;/sup&gt; (4/jour) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose-Supr&#234;me.html&quot; title=&quot;M&#233;tamorphose supr&#234;me&quot;&gt;m&#233;tamorphose supr&#234;me&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayons-Prismatiques.html&quot; title=&quot;Rayons prismatiques&quot;&gt;rayons prismatiques&lt;/a&gt;&lt;/i&gt; (DD 22)&lt;/li&gt;&lt;li&gt;6&lt;sup&gt;e&lt;/sup&gt; (6/jour) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;clair-Multiple.html&quot; title=&quot;&#201;clair multiple&quot;&gt;&#233;clair multiple&lt;/a&gt;&lt;/i&gt; (DD 21), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flamme-Contagieuse.html&quot; title=&quot;Flamme contagieuse&quot;&gt;flamme contagieuse&lt;/a&gt;&lt;/i&gt;&lt;sup&gt;*&lt;/sup&gt; (DD 21), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mauvais-Oeil.html&quot; title=&quot;Mauvais œil&quot;&gt;mauvais oeil&lt;/a&gt;&lt;/i&gt; (DD 21)&lt;/li&gt;&lt;li&gt;5&lt;sup&gt;e&lt;/sup&gt; (7/jour) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fosse-Affam&#233;e.html&quot; title=&quot;Fosse affam&#233;e&quot;&gt;fosse affam&#233;e&lt;/a&gt;&lt;/i&gt;&lt;sup&gt;*&lt;/sup&gt; (DD 20), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose.html&quot; title=&quot;M&#233;tamorphose&quot;&gt;m&#233;tamorphose&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Force.html&quot; title=&quot;Mur de force&quot;&gt;mur de force&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;portation.html&quot; title=&quot;T&#233;l&#233;portation&quot;&gt;t&#233;l&#233;portation&lt;/a&gt;&lt;/i&gt;&lt;/li&gt;&lt;li&gt;4&lt;sup&gt;e&lt;/sup&gt; (7/jour) — &lt;i&gt;&l